(7, 'Nature of inquiry', '<p><span style="background-color:transparent;color:#000000;">Add a statement that frames the inquiry taking place.</span></p>', 'student', 3, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
(7, 'Factual Inquiry Questions', '<p><span style="background-color:transparent;color:#000000;">Where applicable, add an inquiry question that has a right or wrong answer. Typically these require a student to know who, what, when, where.</span></p>', 'student', 4, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
(7, 'Conceptual Inquiry Questions', '<p><span style="background-color:transparent;color:#000000;">Where applicable, add an inquiry question that requires understanding or transferable knowledge. Typically these questions require a student to know how.</span></p>', 'student', 5, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
(7, 'Debatable Inquiry Questions', '<p><span style="background-color:transparent;color:#000000;">Where applicable, add an inquiry question that requires consideration from multiple perspectives. Typically these questions require a student to form an opinion.</span></p>', 'student', 6, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
(7, 'Key Learning Behaviours', '<p><span style="background-color:transparent;color:#000000;">Add information about the learning behaviours that students can demonstrate and practise through this lesson to enable them to access learning and interact with others productively in the community.</span></p>', 'student', 7, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
(7, 'Differentiation Strategies', '<p><span style="background-color:transparent;color:#000000;">Add strategies that will be used to stretch and challenge high achieving students.</span></p><p><span style="background-color:transparent;color:#000000;">Add strategies that will be used to support low achieving students.</span><br>&nbsp;</p>', 'staff', 8, '2023-03-27 19:23:59', '2023-03-27 19:23:59', null),
